import{_ as r,c as o,o as n,b0 as d}from"./chunks/framework.Becqh7-x.js";const s="/linux-dev-docs/assets/image-20260112192211139.dgLCoo09.png",e="/linux-dev-docs/assets/image-20260112192224484.B9xtkSsJ.png",b=JSON.parse('{"title":"LV005-文件系统简介","description":null,"frontmatter":{"title":"LV005-文件系统简介","date":"2026-01-12T19:20:39.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/img/rootfs/126d2cca522729ff2700efb1","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2026-01-12T19:20:39.671Z","fulluuid":"f2700efb154a4c878deb82128d4decf7","useduuid":"f2700efb1"}},"headers":[],"relativePath":"sdoc/img/rootfs/126d2cca522729ff2700efb1.md","filePath":"sdoc/15-系统镜像/30-rootfs/LV005-文件系统简介.md","lastUpdated":1768604092000}'),a={name:"sdoc/img/rootfs/126d2cca522729ff2700efb1.md"};function g(i,t,l,h,c,p){return n(),o("div",null,[...t[0]||(t[0]=[d('<h1 id="lv005-文件系统简介" tabindex="-1">LV005-文件系统简介 <a class="header-anchor" href="#lv005-文件系统简介" aria-label="Permalink to &quot;LV005-文件系统简介&quot;">​</a></h1><h2 id="一、文件系统" tabindex="-1">一、文件系统 <a class="header-anchor" href="#一、文件系统" aria-label="Permalink to &quot;一、文件系统&quot;">​</a></h2><h3 id="_1-什么是文件系统" tabindex="-1">1. 什么是文件系统 <a class="header-anchor" href="#_1-什么是文件系统" aria-label="Permalink to &quot;1. 什么是文件系统&quot;">​</a></h3><p>文件系统（File System）是 <strong>操作系统用于管理存储设备（如硬盘、SSD、U 盘）上数据存储和访问的逻辑机制</strong>，核心功能包括：</p><ul><li><strong>数据组织</strong>：定义文件和目录的结构，管理元数据（如文件名、大小、权限、时间戳）。</li><li><strong>存储分配</strong>：决定数据在物理存储介质上的分布方式（如块分配、碎片整理）。</li><li><strong>访问控制</strong>：通过权限机制限制用户或程序对文件的读写操作。</li><li><strong>容错与恢复</strong>：提供日志、冗余校验等机制确保数据一致性（如断电恢复）。</li></ul><p>简单来说就是：操作系统中负责管理和存储文件信息的软件机构称为文件管理系统，简称文件系统。<strong>文件系统</strong> 决定着从存储设备中对文件进行 <strong>命名</strong>、 <strong>存储</strong> 和 <strong>检索</strong> 的方式。</p><h3 id="_2-为什么要文件系统" tabindex="-1">2. 为什么要文件系统 <a class="header-anchor" href="#_2-为什么要文件系统" aria-label="Permalink to &quot;2. 为什么要文件系统&quot;">​</a></h3><p>如果没有文件系统，存储设备会将大量数据简单地堆积存储，如此一来数据间便无法区分。</p><p>文件系统的命名源于过去的纸质数据管理系统。纸质系统中，我们将文档保留为纸质文件，然后将其存放在各个目录中。试想如若没有分类，存放文件的房间便到处都会堆着杂乱无章的文件。</p><p><img src="'+s+'" alt="image-20260112192211139"></p><p>然而，有了文件系统之后，一切便会全然不同：</p><p><img src="'+e+'" alt="image-20260112192224484"></p><p>但也不能说文件系统的功能仅限于整理数据。空间管理，元数据，数据加密，文件访问控制和数据完整性同样是文件系统所具备的功能。</p><h3 id="_3-文件系统的分类" tabindex="-1">3. 文件系统的分类 <a class="header-anchor" href="#_3-文件系统的分类" aria-label="Permalink to &quot;3. 文件系统的分类&quot;">​</a></h3><p>文件系统可按不同维度分类，以下是常见分类方式：</p><h4 id="_3-1-按存储介质分类" tabindex="-1">3.1 按存储介质分类 <a class="header-anchor" href="#_3-1-按存储介质分类" aria-label="Permalink to &quot;3.1 按存储介质分类&quot;">​</a></h4><table tabindex="0"><thead><tr><th><strong>类型</strong></th><th><strong>描述</strong></th><th><strong>示例</strong></th></tr></thead><tbody><tr><td><strong>磁盘文件系统</strong></td><td>用于传统硬盘（HDD）或固态硬盘（SSD）</td><td>NTFS、Ext4、XFS、ZFS</td></tr><tr><td><strong>闪存文件系统</strong></td><td>针对闪存设备（U 盘、SD 卡、SSD）优化，减少写入磨损</td><td>FAT32、exFAT、F2FS、JFFS2</td></tr><tr><td><strong>网络文件系统</strong></td><td>允许通过网络访问远程存储资源</td><td>NFS、SMB/CIFS、GlusterFS</td></tr><tr><td><strong>内存文件系统</strong></td><td>数据存储在内存中，重启后丢失，用于临时文件或加速访问</td><td>tmpfs、ramfs</td></tr></tbody></table><h4 id="_3-2-按设计用途分类" tabindex="-1">3.2 按设计用途分类 <a class="header-anchor" href="#_3-2-按设计用途分类" aria-label="Permalink to &quot;3.2 按设计用途分类&quot;">​</a></h4><table tabindex="0"><thead><tr><th><strong>类型</strong></th><th><strong>描述</strong></th><th><strong>示例</strong></th></tr></thead><tbody><tr><td><strong>通用文件系统</strong></td><td>适用于多种日常场景，支持标准文件操作</td><td>NTFS、Ext4、APFS</td></tr><tr><td><strong>日志文件系统</strong></td><td>通过日志记录操作，确保崩溃后快速恢复数据一致性</td><td>Ext4、XFS、ReiserFS</td></tr><tr><td><strong>分布式文件系统</strong></td><td>数据分散在多个节点，提供高可用性和扩展性</td><td>HDFS、Ceph、GlusterFS</td></tr><tr><td><strong>数据库文件系统</strong></td><td>专为数据库设计的存储结构，优化随机读写性能</td><td>Oracle ASM、MySQL InnoDB</td></tr></tbody></table><h4 id="_3-3-按操作系统分类" tabindex="-1">3.3 按操作系统分类 <a class="header-anchor" href="#_3-3-按操作系统分类" aria-label="Permalink to &quot;3.3 按操作系统分类&quot;">​</a></h4><table tabindex="0"><thead><tr><th><strong>类型</strong></th><th><strong>描述</strong></th><th><strong>示例</strong></th></tr></thead><tbody><tr><td><strong>Windows 文件系统</strong></td><td>微软生态专用，兼容性强</td><td>NTFS、FAT32、exFAT、ReFS</td></tr><tr><td><strong>Linux 文件系统</strong></td><td>开源系统主流选择，支持高级功能</td><td>Ext4、XFS、Btrfs、ZFS</td></tr><tr><td><strong>macOS 文件系统</strong></td><td>苹果生态优化，强调数据安全和快照</td><td>APFS、HFS+</td></tr></tbody></table><h2 id="二、常用文件系统" tabindex="-1">二、常用文件系统 <a class="header-anchor" href="#二、常用文件系统" aria-label="Permalink to &quot;二、常用文件系统&quot;">​</a></h2><h3 id="_1-本地文件系统" tabindex="-1">1. 本地文件系统 <a class="header-anchor" href="#_1-本地文件系统" aria-label="Permalink to &quot;1. 本地文件系统&quot;">​</a></h3><table tabindex="0"><thead><tr><th><strong>文件系统</strong></th><th><strong>特点</strong></th><th><strong>应用场景</strong></th></tr></thead><tbody><tr><td><strong>NTFS</strong></td><td>Windows 默认系统，支持大文件（&gt; 4GB）、ACL 权限、加密、日志</td><td>Windows 系统盘、大容量存储</td></tr><tr><td><strong>FAT32</strong></td><td>兼容性强（跨设备），但单文件最大 4GB，无权限控制</td><td>U 盘、SD 卡、旧设备兼容</td></tr><tr><td><strong>exFAT</strong></td><td>FAT32 升级版，支持大文件（16EB），适合闪存设备</td><td>大容量移动硬盘、相机存储卡</td></tr><tr><td><strong>Ext4</strong></td><td>Linux 主流系统，日志功能完善，稳定性高</td><td>Linux 系统盘、服务器存储</td></tr><tr><td><strong>XFS</strong></td><td>高性能，支持超大容量（8EB）和高并发，适合海量数据</td><td>数据中心、视频编辑存储</td></tr><tr><td><strong>Btrfs</strong></td><td>支持快照、压缩、RAID、数据校验，功能丰富但成熟度待提升</td><td>需要高级功能的 Linux 环境</td></tr><tr><td><strong>APFS</strong></td><td>苹果专用，优化 SSD 性能，支持加密、快照、空间共享</td><td>macOS 系统盘、Time Machine</td></tr></tbody></table><h3 id="_2-网络与分布式文件系统" tabindex="-1">2. 网络与分布式文件系统 <a class="header-anchor" href="#_2-网络与分布式文件系统" aria-label="Permalink to &quot;2. 网络与分布式文件系统&quot;">​</a></h3><table tabindex="0"><thead><tr><th><strong>文件系统</strong></th><th><strong>特点</strong></th><th><strong>应用场景</strong></th></tr></thead><tbody><tr><td><strong>NFS</strong></td><td>基于网络的 UNIX 协议，支持多客户端共享访问</td><td>Linux/Unix 跨服务器文件共享</td></tr><tr><td><strong>SMB/CIFS</strong></td><td>Windows 原生协议，跨平台共享（Windows/Linux/macOS）</td><td>企业文件共享、打印机共享</td></tr><tr><td><strong>GlusterFS</strong></td><td>分布式存储，横向扩展，无元数据服务器</td><td>云计算、大数据存储</td></tr><tr><td><strong>Ceph</strong></td><td>统一存储架构（块/文件/对象），高可用性和强一致性</td><td>云平台、容器存储后端</td></tr><tr><td><strong>HDFS</strong></td><td>Hadoop 生态核心组件，适合流式大数据处理</td><td>大数据分析（如 Hadoop 集群）</td></tr></tbody></table><h3 id="_3-特殊用途文件系统" tabindex="-1">3. 特殊用途文件系统 <a class="header-anchor" href="#_3-特殊用途文件系统" aria-label="Permalink to &quot;3. 特殊用途文件系统&quot;">​</a></h3><table tabindex="0"><thead><tr><th><strong>文件系统</strong></th><th><strong>特点</strong></th><th><strong>应用场景</strong></th></tr></thead><tbody><tr><td><strong>ZFS</strong></td><td>集成卷管理、快照、压缩、数据完整性校验，资源占用高</td><td>企业级存储、NAS 设备</td></tr><tr><td><strong>tmpfs</strong></td><td>数据存储在内存中，读写极快，重启后丢失</td><td>临时文件缓存、Docker 容器</td></tr><tr><td><strong>F2FS</strong></td><td>专为闪存设计，减少写入放大，延长寿命</td><td>Android 手机存储、SSD 优化</td></tr></tbody></table><h2 id="三、文件系统的发展" tabindex="-1">三、文件系统的发展 <a class="header-anchor" href="#三、文件系统的发展" aria-label="Permalink to &quot;三、文件系统的发展&quot;">​</a></h2><p>文件系统由一套数据结构、连接电路、抽象概念和 API 构成。它们协同工作，步调一致地管理任何类型存储设备上的任何类型文件。每种操作系统会使用特定的文件系统来管理文件。</p><p>过去，Microsoft 曾在 <strong>MS-DOS</strong> 和 <strong>Windows 9x</strong> 家族系统中使用过 <strong>FAT</strong> （FAT12，FAT16 和 FAT32）。但自 Windows <strong>NT 3.1</strong> 开始，Microsoft 研发了 <strong>新技术文件系统（NTFS）</strong>。比起 FAT32，NTFS 具有诸多多优势，如支持更大的文件，更长的文件名，数据加密，访问管理，日志记录等等。</p><p>从那时起，NTFS 就一直是 Window NT 家族（2000，XP，Vista，7、10 等）的默认文件系统。不过，NTFS 并不适用于非 Windows 环境。例如，在 Mac OS 上，我们 <strong>只能读取</strong> NTFS 格式存储设备（如闪存）上的内容，但无法写入任何内容，除非安装具有写入支持的 NTFS 驱动程序。</p><p>2006 年，Microsoft 创建 <strong>扩展文件分配表（exFAT）</strong> 文件系统，exFAT 堪称 NTFS 的精简版。exFAT 的设计面向对象是大容量可移动设备（例如外部硬盘，USB 驱动器和存储卡）。它也是 <strong>SDXC</strong> <strong>卡</strong> 使用的默认文件系统。与 NTFS 不同，exFAT 在非 Windows 环境（包括 Mac OS）上也支持 <strong>读写</strong> ，这也使其成为最佳的高容量可移动存储设备跨平台文件系统。因此基本上可以这么说，如果想同时在 Windows、Mac 和 Linux 上使用同一块可移动磁盘，就需要将其格式化为 exFAT 格式。</p><p>多年以来，Apple 也在研发利用自己的各种文件系统，这就包括 <strong>分层文件系统（HFS）</strong>, <strong>HFS+</strong> 以及后来推出的 <strong>苹果文件系统（APFS）</strong>。和 NTFS 类似，APFS 也是一个日志文件系统。自苹果在 2017 年推出 <strong>OS X High Sierra</strong> 以来，APFS 一直使用至今。</p><p>文件系统中的 <strong>扩展文件系统（ext）</strong> 家族是专门为 Linux 内核（即 Linux 操作系统的核心）创建的。<strong>ext</strong> 的第一版发布于 1991 年，但不久便在 1993 年被 <strong>第二代扩展文件系统</strong> （<strong>ext2）</strong> 取代。进入 21 世纪，针对 Linux 开发的具有日志功能的 <strong>第三代扩展文件系统</strong> （<strong>ext3）</strong> 和 <strong>第四代扩展文件系统 （ext4）</strong> 也相继出现。如今，<strong>ext4</strong> 成为Linux的许多发行版本中的默认文件系统，这就包括 <a href="https://en.wikipedia.org/wiki/Debian" target="_blank" rel="noreferrer">Debian</a> 和 <a href="https://en.wikipedia.org/wiki/Ubuntu" target="_blank" rel="noreferrer">Ubuntu</a>。</p><blockquote><p>参考资料：</p><p><a href="https://www.cnblogs.com/cxuanBlog/p/12565601.html" target="_blank" rel="noreferrer">简直不要太硬了！一文带你彻底理解文件系统 - 程序员 cxuan - 博客园</a></p><p><a href="https://www.cnblogs.com/leehang/articles/18819004" target="_blank" rel="noreferrer">文件系统详解：概念、分类与常用系统 - LeeHang - 博客园</a></p><p><a href="https://www.freecodecamp.org/chinese/news/file-systems-architecture-explained/" target="_blank" rel="noreferrer">文件系统是什么？介绍几种计算机文件系统及其运行原理</a></p><p><a href="https://cloud.tencent.com/developer/article/1791275" target="_blank" rel="noreferrer">Linux 根文件系统（rootfs 原理详解）-腾讯云开发者社区-腾讯云</a></p></blockquote>',36)])])}const u=r(a,[["render",g]]);export{b as __pageData,u as default};
